              Delete image
            </button>
          </article>
        </div>
      </section>
    </main>

    <dialog id="confirm-delete" aria-labelledby="confirm-title" aria-describedby="confirm-copy">
      <button type="button" class="close-button" aria-label="Close dialog">×</button>
      <div class="dialog-card">
        <h2 class="dialog-heading" id="confirm-title">Delete this image?</h2>
        <p class="dialog-copy" id="confirm-copy">
          This will remove the image from your library. You can’t undo this action after it’s confirmed.
        </p>

        <div class="dialog-actions">
          <button type="button" class="secondary" data-close autofocus>Cancel</button>
          <button type="button" class="primary" data-confirm>Delete image</button>
        </div>
      </div>
    </dialog>

    <script>
      const dialog = document.getElementById("confirm-delete");
      const trigger = document.querySelector(".trigger");
      const closeButtons = dialog.querySelectorAll("[data-close], .close-button");
      const confirmButton = dialog.querySelector("[data-confirm]");

      const openDialog = () => {
        if (!dialog.open) {
          dialog.showModal();
        }
      };

      const closeDialog = () => {
        if (dialog.open) {
          dialog.close();
        }
      };

      trigger.addEventListener("click", openDialog);
      closeButtons.forEach((button) => button.addEventListener("click", closeDialog));
      confirmButton.addEventListener("click", closeDialog);
    </script>
