         font-size: clamp(1.65rem, 2vw + 1rem, 2.6rem);
         line-height: 1.1;
         letter-spacing: -0.03em;
       }

       .subtitle {
         margin: 12px 0 0;
         max-width: 60ch;
         color: var(--muted);
         line-height: 1.6;
       }

       .content {
         display: grid;
         gap: 22px;
         padding: 24px 28px 30px;
       }

       .image-card {
         background: var(--surface-strong);
         border: 1px solid var(--border);
         border-radius: 24px;
         padding: 16px;
       }

       .image-frame {
         aspect-ratio: 16 / 10;
         border-radius: 18px;
         overflow: hidden;
         background: linear-gradient(135deg, #dbeafe, #eff6ff 36%, #ffffff 100%);
         position: relative;
       }

       .image-frame img {
         display: block;
         width: 100%;
         height: 100%;
         object-fit: cover;
       }

       .image-meta {
         display: flex;
         justify-content: space-between;
         gap: 16px;
         align-items: center;
         margin-top: 16px;
       }

       .image-title {
         margin: 0;
         font-size: 0.82rem;
         text-transform: uppercase;
         letter-spacing: 0.08em;
         color: var(--muted);
       }

       .image-meta dd {
         margin: 0;
         font-weight: 600;
       }

       .trigger,
       .secondary,
       .primary {
         appearance: none;
         border: 0;
         border-radius: 999px;
         font: inherit;
         font-weight: 700;
         line-height: 1;
         cursor: pointer;
         transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease;
       }

       .trigger {
         align-self: start;
         background: linear-gradient(135deg, var(--danger), var(--danger-strong));
         color: #fff;
         padding: 0.95rem 1.3rem;
         box-shadow: 0 14px 26px rgba(220, 38, 38, 0.24);
       }

       .secondary,
       .primary {
         padding: 0.92rem 1.15rem;
       }

       .secondary {
         background: #edf2ff;
         color: #27406a;
       }

       .primary {
         background: linear-gradient(135deg, var(--danger), var(--danger-strong));
         color: #fff;
       }

       .trigger:hover,
       .secondary:hover,
       .primary:hover {
         transform: translateY(-1px);
       }

       .trigger:focus-visible,
       .secondary:focus-visible,
       .primary:focus-visible,
       .close-button:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       .delete-note {
         color: var(--muted);
         font-size: 0.95rem;
         margin: 0;
       }

       .image-stats {
         margin: 10px 0 0;
       }

       dialog {
         width: min(92vw, 520px);
         border: 1px solid rgba(24, 32, 51, 0.12);
         border-radius: 24px;
         padding: 0;
         box-shadow: 0 30px 80px rgba(15, 23, 42, 0.28);
         background: #fff;
         color: var(--text);
       }

       dialog::backdrop {
         background: rgba(15, 23, 42, 0.58);
         backdrop-filter: blur(4px);
       }

       .dialog-card {
         padding: 24px;
       }

       .dialog-heading {
         margin: 0;
         font-size: 1.35rem;
         letter-spacing: -0.02em;
       }

       .dialog-copy {
         margin: 12px 0 0;
         color: var(--muted);
         line-height: 1.6;
       }

       .dialog-actions {
         display: flex;
         gap: 12px;
         justify-content: flex-end;
         margin-top: 24px;
         flex-wrap: wrap;
       }

       .close-button {
         position: absolute;
         top: 16px;
         right: 16px;
         width: 40px;
         height: 40px;
         border-radius: 999px;
         border: 1px solid rgba(24, 32, 51, 0.12);
         background: #fff;
         color: var(--muted);
         cursor: pointer;
       }

       @media (max-width: 640px) {
         .preview-header,
         .content {
           padding-left: 18px;
           padding-right: 18px;
         }

         .preview-header {
           padding-top: 18px;
         }

')

