const fs = require('fs');
const assert = require('assert');
const { chromium } = require('playwright');
const axePath = require.resolve('axe-core/axe.min.js');
const html = fs.readFileSync('index.html', 'utf8');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 960 } });
  await page.setContent(html, { waitUntil: 'load' });
  await page.addScriptTag({ path: axePath });

  const collect = async () => {
    const results = await page.evaluate(async () => await window.axe.run(document));
    return results.violations.filter(v => !v.tags?.includes('best-practice')).map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target) }));
  };

  const closedViolations = await collect();
  assert.deepStrictEqual(closedViolations, []);

  await page.getByRole('button', { name: 'Delete image' }).click();
  await page.waitForFunction(() => document.getElementById('confirm-delete').open === true);
  assert.strictEqual(await page.evaluate(() => document.activeElement.textContent), 'Cancel');

  const openViolations = await collect();
  assert.deepStrictEqual(openViolations, []);

  await page.getByRole('button', { name: 'Cancel' }).click();
  await page.waitForFunction(() => document.getElementById('confirm-delete').open === false);
  assert.strictEqual(await page.evaluate(() => document.activeElement.className), 'trigger');

  console.log(JSON.stringify({ closedViolations, openViolations, focusReturned: true }));
  await browser.close();
})();
